<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'
import { addRandom, categoryById } from '../utils'
import { useTraining } from '../stores/training'
import Modal from './Modal.vue'
import TaskPreview from './TaskPreview.vue'
const props = defineProps({ profileId: Number, list: Object, lists: Array })
const emit = defineEmits(['close'])
const router = useRouter(), training = useTraining()
const items = ref([]), selected = ref(new Set()), loading = ref(true), busy = ref(false), error = ref(''), randomCount = ref(10)
const counts = computed(() => items.value.reduce((a, i) => { a[i.status]++; return a }, { correct: 0, mistake: 0, new: 0 }))
onMounted(async () => {
  try {
    const sources = props.lists || [props.list]
    items.value = (await Promise.all(sources.map(async list => (await api(`/profiles/${props.profileId}/lists/${list.id}/items`)).map(item => ({ ...item, listName: sources.length > 1 ? list.name : '' }))))).flat()
  } catch (e) { error.value = e.message } finally { loading.value = false }
})
function addStatus(status) { selected.value = new Set([...selected.value, ...items.value.filter(i => (!status || i.status === status) && !i.needs_review).map(i => i.id)]) }
function toggle(id) { const set = new Set(selected.value); set.has(id) ? set.delete(id) : set.add(id); selected.value = set }
async function start() {
  busy.value = true; error.value = ''
  try {
    await training.start(props.profileId, (props.lists || [props.list]).map(l => l.id), [...selected.value])
    emit('close'); router.push({ path: '/training', query: { session: training.session.id } })
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
</script>
<template><Modal :title="list.name" :subtitle="`${categoryById(list.category).name} · Выберите задания для тренировки`" wide @close="!busy && emit('close')"><div class="modal-body selection-body"><div class="selection-summary"><span class="badge green"><Icon name="CircleCheck" :size="12" />Изученные {{ counts.correct }}</span><span class="badge rose"><Icon name="CircleX" :size="12" />С ошибками {{ counts.mistake }}</span><span class="badge neutral"><Icon name="Circle" :size="12" />Новые {{ counts.new }}</span></div><div class="quick-select"><button class="btn secondary sm" @click="addStatus('mistake')"><Icon name="CircleX" :size="13" />С ошибками</button><button class="btn secondary sm" @click="addStatus('new')"><Icon name="Sparkles" :size="13" />Новые</button><div class="random-select"><button class="btn secondary sm" @click="selected = addRandom(items, selected, randomCount)"><Icon name="Shuffle" :size="13" />+ случайных</button><select v-model="randomCount" aria-label="Количество случайных заданий"><option v-for="n in [10,20,30,40,50]" :key="n" :value="n">{{ n }}</option></select></div><span class="select-spacer"></span><button class="text-action" @click="addStatus()">Выбрать все</button><button class="text-action muted" @click="selected = new Set()">Снять</button></div><div class="selection-hint"><Icon name="Info" :size="12" />Быстрый выбор добавляет задания к уже отмеченным</div><div v-if="loading" class="loading"><Icon name="LoaderCircle" class="spin" />Загружаем задания…</div><div v-else class="selection-items"><label v-for="item in items" :key="item.id" class="selection-row" :class="[item.status, { disabled: item.needs_review }]"><input type="checkbox" :checked="selected.has(item.id)" :disabled="item.needs_review || busy" @change="toggle(item.id)" /><div class="flex-1 min-w-0"><TaskPreview :item="item" :category="list.category" /></div><Icon :name="item.status === 'correct' ? 'CircleCheck' : item.status === 'mistake' ? 'CircleX' : 'Circle'" :size="16" class="selection-status" /></label></div><div v-if="list.review" class="info-banner"><Icon name="AlertCircle" :size="16" />Задания с непроверенным ударением недоступны. Уточните ударение в базе заданий.</div><div v-if="error" class="error-box mt-4">{{ error }}</div></div><footer class="modal-footer"><span class="selection-total">Выбрано <strong>{{ selected.size }}</strong> из {{ items.length }}</span><button class="btn secondary" :disabled="busy" @click="emit('close')">Отмена</button><button class="btn primary" :disabled="!selected.size || busy" @click="start"><Icon :name="busy ? 'LoaderCircle' : 'Play'" :class="{ spin: busy }" :size="16" />Начать тренировку<span class="start-count">{{ selected.size }}</span></button></footer></Modal></template>
<style scoped>
.selection-summary{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:19px}.selection-summary .badge{font-size:10px;padding:6px 10px}.quick-select{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.quick-select .btn{font-size:10px;padding:7px 10px}.random-select{display:flex;border:1px solid #e2e8f0;border-radius:8px;background:white}.random-select .btn{border:0;border-radius:8px 0 0 8px}.random-select select{border:0;border-left:1px solid #e7edf4;padding:0 7px;background:none;color:#71859b;font-size:10px;outline:none}.select-spacer{flex:1}.text-action{font-size:10px;color:#649dc4;border:0;background:none;padding:5px 2px}.text-action.muted{color:#a1afbf}.selection-hint{display:flex;align-items:center;gap:6px;font-size:9px;color:#a7b4c3;margin:14px 0}.selection-items{max-height:43vh;overflow:auto;border:1px solid #e7edf4;border-radius:11px}.selection-row{padding:13px;display:flex;align-items:center;gap:13px;border-bottom:1px solid #e9eff5;font-size:12px;cursor:pointer}.selection-row:last-child{border:0}.selection-row.correct{background:#f2fbf6}.selection-row.mistake{background:#fff5f6}.selection-row input{appearance:none;width:16px;height:16px;flex-shrink:0;border:1px solid #d3dfeb;background:#fff;border-radius:5px;cursor:pointer;position:relative}.selection-row input:checked{background:#0284c7;border-color:#0284c7}.selection-row input:checked::after{content:'✓';color:#fff;font-size:11px;position:absolute;left:2px;top:-1px}.selection-row.disabled{opacity:.6;cursor:not-allowed}.selection-status{color:#c1ccd8;flex-shrink:0}.correct .selection-status{color:#85c2a9}.mistake .selection-status{color:#e2a2ac}.selection-total{margin-right:auto;color:#95a5b8;font-size:10px;align-self:center}.selection-total strong{color:#4a92bf;font-weight:500}.start-count{background:#ffffff25;border-radius:5px;padding:1px 6px;margin-left:3px;font-size:10px}@media(max-width:760px){.selection-total{display:none}.selection-summary .badge{font-size:9px;padding:5px 7px}.selection-row{gap:9px;padding:11px}.select-spacer{display:none}.selection-items{max-height:39vh}.quick-select{gap:5px}.text-action{padding:5px}}
</style>
